<?php
session_start();
require __DIR__ . '/../includes/conexao.php';

$erro = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $email = trim($_POST['email'] ?? '');
    $senha = trim($_POST['senha'] ?? '');
    if ($email === '' || $senha === '') {
        $erro = 'E-mail e senha são obrigatórios.';
    } else {
        $stmt = $conexao->prepare('SELECT id_usuario, perfil, nome FROM usuario WHERE email = ? AND senha = ? AND ativo = 1');
        $stmt->bind_param('ss', $email, $senha);
        $stmt->execute();
        $result = $stmt->get_result();
        if ($result->num_rows === 1) {
            $usuario = $result->fetch_assoc();
            $_SESSION['id_usuario'] = $usuario['id_usuario'];
            $_SESSION['perfil'] = $usuario['perfil'];
            $_SESSION['nome'] = $usuario['nome'];
            $destinos = [
                'Aluno' => 'aluno/inicio_aluno.php',
                'Professor' => 'professor/inicio_professor.php',
                'Coordenação' => 'coordenacao/inicio_coordenacao.php',
                'Secretaria' => 'secretaria/inicio_secretaria.php',
            ];
            if (isset($destinos[$usuario['perfil']])) {
                session_regenerate_id(true);
                header('Location: ' . $destinos[$usuario['perfil']]);
                exit();
            }
            $erro = 'Perfil de acesso não reconhecido. Contate a secretaria.';
        } else {
            $erro = 'E-mail ou senha incorretos.';
        }
        $stmt->close();
    }
}
?>
