<script>const toggle=document.getElementById('toggle-password');const password=document.getElementById('senha');toggle.addEventListener('click',()=>{const showing=password.type==='password';password.type=showing?'text':'password';toggle.textContent=showing?'Ocultar':'Mostrar';toggle.setAttribute('aria-label',showing?'Ocultar senha':'Mostrar senha');toggle.setAttribute('aria-pressed',String(showing));});</script></body></html>